const payload = $json.body || $json;
const now = new Date().toISOString();
const preferredLanguage = ((payload.preferred_language || payload.language || payload.lang || 'es').toString().toLowerCase() === 'en') ? 'en' : 'es';
const requestedService = (payload.requested_service || payload.service || payload.current_service || 'general').toString();
const leadStatus = (payload.lead_status || 'NEW').toString();

return [{
  json: {
    workflow_execution_id: $execution.id,
    lead_id: (payload.lead_id || '').toString(),
    name: (payload.name || '').toString(),
    phone: (payload.phone || '').toString(),
    email: (payload.email || '').toString(),
    preferred_language: preferredLanguage,
    requested_service: requestedService,
    lead_source: (payload.lead_source || payload.channel || 'web').toString(),
    conversation_summary: (payload.conversation_summary || '').toString(),
    lead_status: leadStatus,
    appointment_status: (payload.appointment_status || '').toString(),
    created_date: (payload.created_date || now).toString(),
    last_interaction: now,
    extra_data: payload.extra_data || {},
    session_id: (payload.session_id || '').toString(),
    customer_id: (payload.customer_id || '').toString(),
    crmConfigured: Boolean(((payload.crm_api_url || payload.crmApiUrl || payload.config?.crm_api_url || '').toString().trim().length > 4) || payload.crmConfigured || payload.crm_configured)
  }
}];

const p = $json;
const lead = p?.json || p;
const response = (lead.body && typeof lead.body === 'object') ? lead.body : lead;

return [{
  json: {
    success: response.success !== false,
    lead_id: response.lead_id || response.id || lead.lead_id || `lead_${Date.now()}`,
    status: response.lead_status || lead.lead_status || 'NEW',
    service: lead.requested_service || 'general',
    workflow_execution_id: lead.workflow_execution_id,
    source: lead.lead_source,
    session_id: lead.session_id,
    customer_id: lead.customer_id,
    message: 'lead_saved',
    payload: {
      name: lead.name,
      phone: lead.phone,
      email: lead.email,
      preferred_language: lead.preferred_language
    }
  }
}];

const lead = $json;
return [{
  json: {
    success: false,
    lead_id: lead.lead_id || `lead_${Date.now()}`,
    status: lead.lead_status || 'NEW',
    service: lead.requested_service || 'general',
    workflow_execution_id: lead.workflow_execution_id,
    source: lead.lead_source || 'web',
    session_id: lead.session_id || '',
    customer_id: lead.customer_id || '',
    message: 'crm_not_configured',
    payload: {
      name: lead.name || '',
      phone: lead.phone || '',
      email: lead.email || '',
      preferred_language: lead.preferred_language || 'es'
    }
  }
}];
